    "optionsEn": [
      "Stable equilibrium at $x = -4$, Unstable at $x = 4$",
      "Stable equilibrium at $x = 4$, Unstable at $x = -4$",
      "Stable at both $x = \\pm 4$",
      "Unstable at both $x = \\pm 4$"
    ],
    "optionsAr": [
      "اتزان مستقر عند $x = -4$، وغير مستقر عند $x = 4$",
      "اتزان مستقر عند $x = 4$، وغير مستقر عند $x = -4$",
      "مستقر عند كلا الموضعين $x = \\pm 4$",
      "غير مستقر عند كلا الموضعين $x = \\pm 4$"
    ],
    "correctAnswer": "Stable equilibrium at $x = 4$, Unstable at $x = -4$",
    "correctIndex": 1,
    "hintEn": "Equilibrium points satisfy V'(x) = 0. Stability requires V''(x) > 0 (local minimum of potential).",
    "hintAr": "الاتزان يتحقق بانعدام المشتقة الأولى V'(x) = 0. الاتزان المستقر يشترط V''(x) > 0 (صغرى لطاقة الوضع).",
    "stepByStepSolutionEn": [
      "1. Find equilibrium positions: $V'(x) = 3x^2 - 48 = 3(x^2 - 16) = 0 \\implies x = \\pm 4$.",
      "2. Second derivative: $V''(x) = 6x$.",
      "3. At $x = 4$: $V''(4) = 6(4) > 0 \\implies$ local minimum of $V$, which is **STABLE** equilibrium.",
      "4. At $x = -4$: $V''(-4) = -6(4) < 0 \\implies$ local maximum of $V$, which is **UNSTABLE** equilibrium."
    ],
    "stepByStepSolutionAr": [
      "١. نقاط الاتزان: $V'(x) = 3x^2 - 48 = 0 \\implies x = \\pm 4$.",
      "٢. المشتقة الثانية: $V''(x) = 6x$.",
      "٣. عند $x = 4$: $V'' > 0 \\implies$ صغرى لطاقة الوضع، إذن اتزان مستقر.",
      "٤. عند $x = -4$: $V'' < 0 \\implies$ عظمى لطاقة الوضع، إذن اتزان غير مستقر."
    ],
    "teacherTipEn": "A marble at the bottom of a bowl is stable (V''>0); balanced on a hilltop is unstable (V''<0).",
    "teacherTipAr": "الكرة في قاع الوعاء في اتزان مستقر (V''>0)، بينما أعلى التل في اتزان غير مستقر (V''<0)."
