    "questionAr": "تحت تأثير مجال قوى مركزية، كانت السرعة المستعرضة لجسيم $v_1 = 4\\text{ م/ث}$ عند بعد $r_1 = 6\\text{ م}$. احسب سرعته المستعرضة $v_2$ عندما يصبح بعده $r_2 = 3\\text{ م}$.",
