      "Integrate with respect to $x$: $U(x, y) = x^2 + g(y)$.",
      "Differentiate with respect to $y$: $\\frac{\\partial U}{\\partial y} = g'(y) = 4y \\implies g(y) = 2y^2 + C$.",
      "With $U(0, 0) = 0$, $C = 0$.",
      "Thus, $U(x, y) = x^2 + 2y^2$."
