    "difficulty": "hots",
    "questionEn": "A satellite orbits in a circular trajectory with orbital speed $v_0 = 100\\text{ km/s}$. What minimum escape velocity $v_{\\text{esc}}$ must be imparted to it to completely overcome the gravitational field and reach infinity with zero kinetic energy?",
    "questionAr": "يدور قمر صناعي في مسار دائري بسرعة مدارية $v_0 = 100\\text{ كم/ث}$. ما هي أقل سرعة إفلات $v_{\\text{هروب}}$ يجب إكسابها له ليتخلص تماماً من مجال الجاذبية ويصل إلى اللانهاية؟",
