    "difficulty": "hots",
    "questionEn": "A conservative force field has the potential energy function $V(x, y) = 2(x^2 + y^2)\\text{ J}$. Find the work done by this force field in moving a particle from origin $A(0, 0)$ to point $B(3, 4)$ along an arbitrary smooth curve.",
    "questionAr": "مجال قوى محافظ دالة طاقة وضعه $V(x, y) = 2(x^2 + y^2)\\text{ جول}$. احسب الشغل المبذول بواسطة هذا المجال لنقل جسيم من نقطة الأصل $A(0, 0)$ إلى النقطة $B(3, 4)$ عبر أي مسار منحنٍ.",
